(() => {
  const root = document.body || document.documentElement;
  if (!root) {
    return { title: document.title || '', url: window.location.href, elements: [] };
  }

  if (!window.__CDPX_REGISTRY__) {
    try {
      Object.defineProperty(window, '__CDPX_REGISTRY__', {
        value: new Map(),
        writable: true,
        configurable: true,
        enumerable: false
      });
    } catch (_) {
      window.__CDPX_REGISTRY__ = new Map();
    }
  }
  window.__CDPX_REGISTRY__.clear();

  const isInteractive = (el) => {
    const tag = el.tagName.toLowerCase();
    if (['a', 'button', 'input', 'select', 'textarea', 'summary'].includes(tag)) return true;
    if (el.hasAttribute('onclick') || el.getAttribute('role') === 'button' || el.getAttribute('role') === 'link') return true;
    
    // Do not treat plain SVG elements or vector sub-elements as interactive unless explicitly interactive
    if (['svg', 'path', 'g', 'circle', 'rect', 'polygon', 'ellipse', 'line', 'use'].includes(tag)) {
      return false;
    }

    try {
      const style = window.getComputedStyle(el);
      return style.cursor === 'pointer' && style.pointerEvents !== 'none';
    } catch (_) {
      return false;
    }
  };

  const getAccessibleName = (el) => {
    const aria = el.getAttribute('aria-label') || el.getAttribute('title') || el.getAttribute('placeholder');
    if (aria) return aria.trim();

    if (el.labels && el.labels.length > 0) {
      const lbl = el.labels[0].innerText.trim().replace(/\s+/g, ' ');
      if (lbl) return lbl;
    }

    if (el.id) {
      try {
        const lblEl = document.querySelector(`label[for="${CSS.escape(el.id)}"]`);
        if (lblEl && lblEl.innerText) {
          const lbl = lblEl.innerText.trim().replace(/\s+/g, ' ');
          if (lbl) return lbl;
        }
      } catch (_) {}
    }

    if (el.innerText) {
      const txt = el.innerText.trim().replace(/\s+/g, ' ');
      if (txt.length > 0) return txt.slice(0, 60);
    }

    return el.getAttribute('alt') || el.getAttribute('name') || '';
  };

  const elements = [];
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT);
  let node;
  let idx = 1;

  const vectorTags = ['svg', 'path', 'circle', 'rect', 'polygon', 'ellipse', 'line', 'use', 'polyline', 'g', 'span', 'i', 'em', 'strong', 'b'];

  while ((node = walker.nextNode())) {
    if (!isInteractive(node)) continue;

    // Filter out decorative sub-elements if an ancestor interactive element is already captured
    const tag = node.tagName.toLowerCase();
    if (vectorTags.includes(tag)) {
      if (node.closest('a, button, label, [role="button"], [role="link"]')) {
        continue;
      }
    }

    let rect;
    try {
      rect = node.getBoundingClientRect();
    } catch (_) {
      continue;
    }

    // Viewport & visibility culling
    if (rect.width <= 0 || rect.height <= 0) continue;
    if (rect.bottom < 0 || rect.top > window.innerHeight || rect.right < 0 || rect.left > window.innerWidth) continue;

    // Occlusion hit-test
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    try {
      const topEl = document.elementFromPoint(cx, cy);
      if (topEl && !node.contains(topEl) && !topEl.contains(node)) {
        continue;
      }
    } catch (_) {}

    window.__CDPX_REGISTRY__.set(idx, node);

    const role = node.getAttribute('role') || (tag === 'a' ? 'link' : tag);
    const name = getAccessibleName(node);

    elements.push({
      id: idx,
      tag: tag,
      role: role,
      name: name,
      value: node.value !== undefined ? String(node.value) : null,
      x: Math.round(cx),
      y: Math.round(cy),
      w: Math.round(rect.width),
      h: Math.round(rect.height)
    });
    idx++;
  }

  return {
    title: document.title || '',
    url: window.location.href,
    elements: elements
  };
})()